#define MOD 1000000007LL

int main() {
    long long n, k;
    if (scanf("%lld %lld", &n, &k) != 2) return 0;

    if (k > n || k <= 0) {
        printf("0\n");
        return 0;
    }

    /* dp[j] = number of ways to distribute current number of balls
       into j non-empty distinguished boxes */
    long long *dp = (long long *)calloc((size_t)k + 1, sizeof(long long));
    if (!dp) return 0;

    dp[0] = 1;

    for (long long i = 1; i <= n; i++) {
        long long upper = (i < k) ? i : k;
        for (long long j = upper; j >= 1; j--) {
            dp[j] = ( (j * dp[j]) % MOD + dp[j - 1] ) % MOD;
        }
        dp[0] = 0;
    }

    /* dp[k] is Stirling number of the second kind S(n,k),
       multiply by k! for distinguished boxes */
    long long fact = 1;
    for (long long i = 1; i <= k; i++) {
        fact = (fact * i) % MOD;
    }

    long long ans = (dp[k] * fact) % MOD;
    printf("%lld\n", ans);

    free(dp);
    return 0;
}

